  "cyber-assign-day-5": "if (formatWafStatus(true) !== 'WAF_ACTIVE') throw new Error('Status check failed');",
  "cyber-assign-day-6": "if (getGcmRecommendedNonceBits() !== 96) throw new Error('Bits check failed');",
