  "dist-assign-day-12": "const p = routeToPartition('order_101', 4);\nif (p < 0 || p >= 4) throw new Error('Partition routing out of range');",
  "dist-assign-day-13": "if (generateIdempotencyKey('u1', 'o99') !== 'idemp_u1_o99') throw new Error('Key generator failed');",
  "dist-assign-day-14": "if (!formatDlqEntry('m1', 'bad').msgId) throw new Error('DLQ format failed');",
