  "fullstack-js-assign-day-15": "if (extractBearerToken('Bearer abc.def') !== 'abc.def') throw new Error('Bearer extraction failed');",
  "fullstack-js-assign-day-16": "if (isConnectionAlive(Date.now() - 5000) !== true || isConnectionAlive(Date.now() - 40000) !== false) throw new Error('Heartbeat check failed');",
  "fullstack-js-assign-day-17": "const h = formatRateLimitHeaders(100, 0, 60);\nif (h['Retry-After'] !== '60') throw new Error('Rate limit header failed');",
  "fullstack-js-assign-day-18": "if (isAllowedImageMime('image/png') !== true || isAllowedImageMime('application/pdf') !== false) throw new Error('MIME validation failed');",
