  "fullstack-js-assign-day-63": "import { validateRequestSchema } from './solution';\nimport assert from 'assert';\n\nexport async function runTest() {\n  console.log('Testing RFC 9457 Validation Middleware...');\n  const mockSchema = {\n    safeParse: (val: any) => {\n      if (!val || !val.title) return { success: false, error: 'Title required' };\n      return { success: true, data: { title: val.title.trim() } };\n    }\n  };\n  const middleware = validateRequestSchema(mockSchema);\n  let status = 0;\n  let body: any = null;\n  const reqInvalid = { body: {} };\n  const res = {\n    status: (s: number) => { status = s; return res; },\n    json: (b: any) => { body = b; return res; }\n  };\n  middleware(reqInvalid, res, () => {});\n  assert.strictEqual(status, 400, 'Invalid request must return 400');\n  assert.strictEqual(body.type, 'about:blank');\n  console.log('✅ Day 63 Assignment Passed!');\n}",
