  "python-exam-day-1": "assert get_system_banner('AUTH_SRV', '1.0.4') == 'SYSTEM: AUTH_SRV | VERSION: 1.0.4 | STATUS: ONLINE', 'Test 1 Failed'\nassert get_system_banner('CORE', '2.0.0') == 'SYSTEM: CORE | VERSION: 2.0.0 | STATUS: ONLINE', 'Test 2 Failed'\nassert get_system_banner('GATEWAY', '3.1.2') == 'SYSTEM: GATEWAY | VERSION: 3.1.2 | STATUS: ONLINE', 'Test 3 Failed'\nprint('All 3 assertions passed.')",
