  "python-exam-day-12": "assert filter_and_square_evens([2, 5, 8, 11, 14], 4) == [64, 196], 'Test 1 Failed'\nassert filter_and_square_evens([1, 3, 5], 0) == [], 'Test 2 Failed'\nassert filter_and_square_evens([10, 12, 15], 10) == [144], 'Test 3 Failed'\nprint('All 3 assertions passed.')",
  "python-exam-day-13": "assert find_common_customers([101, 102, 103], [102, 103, 104]) == {102, 103}, 'Test 1 Failed'\nassert find_common_customers([1, 2], [3, 4]) == set(), 'Test 2 Failed'\nassert find_common_customers([1, 2, 3], [1, 2, 3]) == {1, 2, 3}, 'Test 3 Failed'\nprint('All 3 assertions passed.')",
  "python-exam-day-14": "assert count_char_frequencies('Hello') == {'h': 1, 'e': 1, 'l': 2, 'o': 1}, 'Test 1 Failed'\nassert count_char_frequencies('A a') == {'a': 2}, 'Test 2 Failed'\nassert count_char_frequencies('') == {}, 'Test 3 Failed'\nprint('All 3 assertions passed.')",
  "python-exam-day-15": "txs = [{'category': 'FOOD', 'amount': 15.5}, {'category': 'TECH', 'amount': 120.0}, {'category': 'FOOD', 'amount': 10.5}]\nassert aggregate_by_category(txs) == {'FOOD': 26.0, 'TECH': 120.0}, 'Test 1 Failed'\nassert aggregate_by_category([]) == {}, 'Test 2 Failed'\nassert aggregate_by_category([{'category': 'UTIL', 'amount': 45.0}]) == {'UTIL': 45.0}, 'Test 3 Failed'\nprint('All 3 assertions passed.')",
  "python-exam-day-16": "acc = BankAccount('Alex', 100.0)\nacc.deposit(50.0)\nassert acc.get_balance() == 150.0, 'Test 1 Failed'\nacc.deposit(-20.0)\nassert acc.get_balance() == 150.0, 'Test 2 Failed'\nacc.deposit(0.0)\nassert acc.get_balance() == 150.0, 'Test 3 Failed'\nprint('All 3 assertions passed.')",
  "python-exam-day-17": "u = UserProfile('sarah', 'sarah@pinit.ai')\nassert u.role == 'STUDENT', 'Test 1 Failed'\ntry:\n    UserProfile('', 'test@pinit.ai')\n    assert False, 'Test 2 Failed'\nexcept ValueError:\n    pass\ntry:\n    UserProfile('valid', 'noatsign')\n    assert False, 'Test 3 Failed'\nexcept ValueError:\n    pass\nprint('All 3 assertions passed.')",
  "python-exam-day-18": "t = Temperature(25.0)\nassert t.kelvin == 298.15, 'Test 1 Failed'\nt.celsius = 0.0\nassert t.kelvin == 273.15, 'Test 2 Failed'\ntry:\n    t.celsius = -300.0\n    assert False, 'Test 3 Failed'\nexcept ValueError:\n    pass\nprint('All 3 assertions passed.')",
  "python-exam-day-19": "e = Employee('Alice', 5000.0)\nassert e.get_total_compensation() == 5000.0, 'Test 1 Failed'\nm = Manager('Bob', 7000.0, 2000.0)\nassert m.get_total_compensation() == 9000.0, 'Test 2 Failed'\nm0 = Manager('Charlie', 6000.0, 0.0)\nassert m0.get_total_compensation() == 6000.0, 'Test 3 Failed'\nprint('All 3 assertions passed.')",
  "python-exam-day-2": "assert identify_data_type(True) == 'BOOLEAN', 'Test 1 Failed'\nassert identify_data_type(42) == 'INTEGER', 'Test 2 Failed'\nassert identify_data_type(3.14) == 'FLOAT', 'Test 3 Failed'\nassert identify_data_type('hello') == 'STRING', 'Test 4 Failed'\nassert identify_data_type([]) == 'OTHER', 'Test 5 Failed'\nprint('All 5 assertions passed.')",
  "python-exam-day-20": "c = Cart()\nc.add_item('Laptop')\nc.add_item('Mouse')\nassert len(c) == 2, 'Test 1 Failed'\nassert str(c) == 'Cart: 2 items', 'Test 2 Failed'\nempty = Cart()\nassert len(empty) == 0 and str(empty) == 'Cart: 0 items', 'Test 3 Failed'\nprint('All 3 assertions passed.')",
  "python-exam-day-21": "cc = CreditCardProcessor(0.02)\nassert cc.process_payment(100.0) == {'net': 98.0, 'fee': 2.0, 'status': 'PROCESSED'}, 'Test 1 Failed'\nupi = UPIProcessor(0.50)\nassert upi.process_payment(100.0) == {'net': 99.50, 'fee': 0.50, 'status': 'PROCESSED'}, 'Test 2 Failed'\ncc2 = CreditCardProcessor(0.05)\nassert cc2.process_payment(200.0) == {'net': 190.0, 'fee': 10.0, 'status': 'PROCESSED'}, 'Test 3 Failed'\nprint('All 3 assertions passed.')",
  "python-exam-day-22": "assert safe_divide_logged(10, 2) == {'result': 5.0, 'error': None}, 'Test 1 Failed'\nassert safe_divide_logged(10, 0) == {'result': None, 'error': 'ZeroDivisionError'}, 'Test 2 Failed'\nassert safe_divide_logged(-20, 4) == {'result': -5.0, 'error': None}, 'Test 3 Failed'\nprint('All 3 assertions passed.')",
  "python-exam-day-23": "logs = ['[INFO] Booting', '[ERROR] Disk Full', '[WARN] High RAM', '[ERROR] Timeout']\nassert count_errors_in_stream(logs) == 2, 'Test 1 Failed'\nassert count_errors_in_stream(['[OK] Normal']) == 0, 'Test 2 Failed'\nassert count_errors_in_stream([]) == 0, 'Test 3 Failed'\nprint('All 3 assertions passed.')",
  "python-exam-day-24": "import json\nassert decode_user_payload('{\"user_id\": 101, \"name\": \"Alex\"}') == {'user_id': 101, 'name': 'Alex'}, 'Test 1 Failed'\nassert decode_user_payload('{\"name\": \"NoId\"}') == {'error': 'INVALID_PAYLOAD'}, 'Test 2 Failed'\nassert decode_user_payload('bad json') == {'error': 'INVALID_PAYLOAD'}, 'Test 3 Failed'\nprint('All 3 assertions passed.')",
  "python-exam-day-25": "@log_execution\ndef add(a, b):\n    return a + b\n\nassert add(3, 4) == {'result': 7, 'function': 'add'}, 'Test 1 Failed'\nassert add(0, 0) == {'result': 0, 'function': 'add'}, 'Test 2 Failed: zero edge case'\n@log_execution\ndef greet(name):\n    return f'Hello, {name}'\nassert greet('PinIT') == {'result': 'Hello, PinIT', 'function': 'greet'}, 'Test 3 Failed'\nprint('All 3 assertions passed.')",
  "python-exam-day-26": "docs = {1: 'Python is great', 2: 'Great systems use Python'}\nidx = build_inverted_index(docs)\nassert idx['python'] == [1, 2], 'Test 1 Failed'\nassert idx['systems'] == [2], 'Test 2 Failed'\nassert build_inverted_index({}) == {}, 'Test 3 Failed'\nprint('All 3 assertions passed.')",
  "python-exam-day-27": "import asyncio\n\nasync def sample(x):\n    return x * 2\n\nasync def runner():\n    res = await fetch_all_metrics([sample(1), sample(2), sample(3)])\n    assert res == [2, 4, 6], 'Test 1 Failed: three coroutines'\n    empty = await fetch_all_metrics([])\n    assert empty == [], 'Test 2 Failed: empty list should return []'\n    single = await fetch_all_metrics([sample(5)])\n    assert single == [10], 'Test 3 Failed: single coroutine result'\n\nasyncio.run(runner())\nprint('All 3 assertions passed.')",
