  "python-exam-day-3": "assert safe_parse_int('120', 0) == 120, 'Test 1 Failed'\nassert safe_parse_int('invalid', 10) == 10, 'Test 2 Failed'\nassert safe_parse_int('-45', 0) == -45, 'Test 3 Failed'\nprint('All 3 assertions passed.')",
